float DriveProcessor::val(const String& id)const{if(auto* p=ap.getRawParameterValue(id))return p->load();return 0;}
void DriveProcessor::set(const String& id,float v){if(auto* p=ap.getParameter(id)){p->beginChangeGesture();p->setValueNotifyingHost(p->convertTo0to1(v));p->endChangeGesture();}}
bool DriveProcessor::isBusesLayoutSupported(const BusesLayout& x)const{return x.getMainInputChannelSet()==x.getMainOutputChannelSet()&&(x.getMainOutputChannelSet()==AudioChannelSet::mono()||x.getMainOutputChannelSet()==AudioChannelSet::stereo());}
void DriveProcessor::prepareToPlay(double sr,int n){baseRate=sr;maxLatency=0;for(int j=0;j<4;++j){overs[j]=std::make_unique<dsp::Oversampling<float>>(size_t(getTotalNumOutputChannels()),size_t(j+1),dsp::Oversampling<float>::filterHalfBandPolyphaseIIR,true,true);overs[j]->initProcessing(size_t(n));overs[j]->reset();maxLatency=std::max(maxLatency,int(std::round(overs[j]->getLatencyInSamples())));}for(auto& d:delay)d.assign(size_t(maxLatency+1),0);delayPos=0;lastOs=-1;core.reset(float(sr));phase={};env={};setLatencySamples(maxLatency);}
